<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
umask(0077);ini_set('display_errors','0');
$root=__DIR__;$reportFile=$root.'/site-icon-deployment.json';$lock=fopen($root.'/site-icon-deployment.lock','c');
if(!$lock||!flock($lock,LOCK_EX|LOCK_NB)||file_exists($reportFile))exit;
$report=['time'=>gmdate('c'),'success'=>false];$replaced=[];
function verifyWorks(bool $ok,string $step):void{if(!$ok)throw new RuntimeException($step);}
$items=json_decode(gzdecode(base64_decode('')),true,512,JSON_THROW_ON_ERROR);
try{
 verifyWorks(PHP_VERSION_ID>=80300,'php_version');
 $configPath=$root.'/private/config.json';$config=json_decode(file_get_contents($configPath),true,512,JSON_THROW_ON_ERROR);
 verifyWorks(($config['origin']??'')==='https://brand-new.tokyo'&&($config['public_indexing']??false)===true,'production_config');
 foreach([32,180,192] as $size){$icon=rtrim($config['legacy_uploads']??'','/').'/2017/08/cropped-街のアイコン2-'.$size.'x'.$size.'.png';$info=is_file($icon)?@getimagesize($icon):false;verifyWorks($info&&$info[2]===IMAGETYPE_PNG&&$info[0]===$size&&$info[1]===$size,'original_icon:'.$size);}
 $backup=$root.'/private/site-icon-before-20261117';verifyWorks(!file_exists($backup),'backup_absent');verifyWorks(mkdir($backup,0700),'backup_create');
 foreach($items as $item){$dest=$root.'/'.$item['path'];verifyWorks($item['before']===null?!file_exists($dest):(is_file($dest)&&hash_file('sha256',$dest)===$item['before']),'previous_hash:'.$item['path']);
  $data=base64_decode($item['data'],true);verifyWorks(is_string($data)&&hash('sha256',$data)===$item['after'],'payload');
  $stage=$backup.'/stage/'.$item['path'];if(!is_dir(dirname($stage)))verifyWorks(mkdir(dirname($stage),0700,true),'stage_directory');verifyWorks(file_put_contents($stage,$data)===strlen($data),'stage_write');
  if(str_ends_with($stage,'.php')){$lines=[];$exit=1;exec(escapeshellarg(PHP_BINARY).' -l '.escapeshellarg($stage).' 2>&1',$lines,$exit);verifyWorks($exit===0,'lint:'.$item['path']);}
  if($item['before']!==null){$copy=$backup.'/previous/'.$item['path'];if(!is_dir(dirname($copy)))mkdir(dirname($copy),0700,true);verifyWorks(copy($dest,$copy)&&hash_file('sha256',$copy)===$item['before'],'backup_code');}
 }
 // Code-only deployment No content or schema changes

 foreach($items as $item){$dest=$root.'/'.$item['path'];$stage=$backup.'/stage/'.$item['path'];verifyWorks(rename($stage,$dest),'replace:'.$item['path']);chmod($dest,0644);$replaced[]=$item;verifyWorks(hash_file('sha256',$dest)===$item['after'],'readback');}
 $report['files']=array_column($items,'after','path');$report['success']=true;$report['storage']='chronicle_posts';$report['data_created']=false;
}catch(Throwable $e){$report['error_class']=get_class($e);if($e instanceof RuntimeException)$report['failed_check']=$e->getMessage();
 foreach(array_reverse($replaced) as $item){if($item['before']!==null){$dest=$root.'/'.$item['path'];copy($backup.'/previous/'.$item['path'],$dest.'.rollback');rename($dest.'.rollback',$dest);chmod($dest,0644);}}
 $report['restored_previous_code']=true;
}
file_put_contents($reportFile,json_encode($report,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));chmod($reportFile,0600);
